begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions,pg_temp;
select no_plan();
insert into auth.users(id) values(md5('p5_alice')::uuid),(md5('p5_bob')::uuid);
insert into public.profiles(id,display_name) values(md5('p5_alice')::uuid,'P5 Alice'),(md5('p5_bob')::uuid,'P5 Bob');
select ok(not has_function_privilege('anon','public.start_ad_hoc_workout()','execute'),'anonymous start denied');
select ok(not has_function_privilege('anon','public.edit_workout(uuid,text,uuid,uuid,integer)','execute'),'anonymous selection edit denied');
select ok(not has_function_privilege('service_role','public.end_workout(uuid,text)','execute'),'service role not granted lifecycle RPC');
select ok((select not bool_or(prosecdef) from pg_proc where oid in ('public.start_ad_hoc_workout()'::regprocedure,'public.edit_workout(uuid,text,uuid,uuid,integer)'::regprocedure,'public.end_workout(uuid,text)'::regprocedure)),'all lifecycle functions enforce invoker privileges/RLS');
set local role authenticated;
select set_config('request.jwt.claims',json_build_object('sub',md5('p5_alice')::uuid,'role','authenticated')::text,true);
select set_config('body_test.session',public.start_ad_hoc_workout()::text,true);
select is(public.start_ad_hoc_workout(),current_setting('body_test.session')::uuid,'repeated start resumes the same active workout');
select is((select count(*)::int from public.workout_sessions where owner_id=auth.uid() and status='in_progress'),1,'only one active workout');
select ok((select source_program_id is null and started_at is not null and finished_at is null from public.workout_sessions where id=current_setting('body_test.session')::uuid),'ad hoc start has accurate defaults and no program');
select throws_ok($$insert into public.workout_sessions(owner_id,name) values(auth.uid(),'Duplicate')$$,'23505',null,'direct duplicate active insertion also denied');
select set_config('body_test.first',public.edit_workout(current_setting('body_test.session')::uuid,'add',(select id from public.exercises where slug='barbell_bench_press'))::text,true);
select is(public.edit_workout(current_setting('body_test.session')::uuid,'add',(select id from public.exercises where slug='barbell_bench_press')),current_setting('body_test.first')::uuid,'duplicate add returns existing selection');
select set_config('body_test.second',public.edit_workout(current_setting('body_test.session')::uuid,'add',(select id from public.exercises where slug='dumbbell_lateral_raise'))::text,true);
select lives_ok($$select public.edit_workout(current_setting('body_test.session')::uuid,'move',null,current_setting('body_test.second')::uuid,-1)$$,'owner reorders selections atomically');
select is((select position from public.workout_exercises where id=current_setting('body_test.second')::uuid),1,'adjacent swap moved second to first');
select is((select position from public.workout_exercises where id=current_setting('body_test.first')::uuid),2,'swap preserved unique order');
select lives_ok($$select public.edit_workout(current_setting('body_test.session')::uuid,'remove',null,current_setting('body_test.first')::uuid)$$,'owner removes an unlogged selection');
select ok((select removed_at is not null and exercise_name_snapshot='Barbell bench press' from public.workout_exercises where id=current_setting('body_test.first')::uuid),'removal preserves ID and name snapshot as a tombstone');
select throws_ok($$insert into public.workout_sets(owner_id,workout_exercise_id,position) values(auth.uid(),current_setting('body_test.first')::uuid,1)$$,'23514',null,'removed selection cannot receive sets');
select lives_ok($$select public.edit_workout(current_setting('body_test.session')::uuid,'remove',null,current_setting('body_test.first')::uuid)$$,'removal retry is idempotent');
select set_config('body_test.readded',public.edit_workout(current_setting('body_test.session')::uuid,'add',(select id from public.exercises where slug='barbell_bench_press'))::text,true);
select isnt(current_setting('body_test.readded')::uuid,current_setting('body_test.first')::uuid,'re-add creates a new selection without destroying old reference');
select set_config('body_test.custom',public.save_custom_exercise(null,'P5 private','compound',(select id from public.movement_patterns where slug='squat'),'{}',array[(select id from public.muscle_groups where slug='quadriceps')],'{}',array[(select id from public.equipment_types where slug='none')],'')::text,true);
select lives_ok($$select public.edit_workout(current_setting('body_test.session')::uuid,'add',current_setting('body_test.custom')::uuid)$$,'owner can select private custom exercises');
select set_config('request.jwt.claims',json_build_object('sub',md5('p5_bob')::uuid,'role','authenticated')::text,true);
select is((select count(*)::int from public.workout_sessions where id=current_setting('body_test.session')::uuid),0,'other owner cannot read session');
select throws_ok($$select public.edit_workout(current_setting('body_test.session')::uuid,'add',(select id from public.exercises where slug='push_up'))$$,'42501',null,'other owner cannot append to session');
select throws_ok($$select public.edit_workout(current_setting('body_test.session')::uuid,'remove',null,current_setting('body_test.second')::uuid)$$,'42501',null,'other owner cannot remove selections');
select throws_ok($$select public.end_workout(current_setting('body_test.session')::uuid,'completed')$$,'42501',null,'other owner cannot finish session');
select set_config('body_test.bob_session',public.start_ad_hoc_workout()::text,true);
select throws_ok($$select public.edit_workout(current_setting('body_test.bob_session')::uuid,'add',current_setting('body_test.custom')::uuid)$$,'42501',null,'another user private exercise cannot be selected');
select lives_ok($$select public.end_workout(current_setting('body_test.bob_session')::uuid,'abandoned')$$,'owner can abandon an empty session');
select ok((select status='abandoned' and completion_status='none' and finished_at>=started_at from public.workout_sessions where id=current_setting('body_test.bob_session')::uuid),'abandon preserves honest state/timestamps');
select set_config('request.jwt.claims',json_build_object('sub',md5('p5_alice')::uuid,'role','authenticated')::text,true);
select lives_ok($$select public.end_workout(current_setting('body_test.session')::uuid,'completed')$$,'owner can finish without fabricating sets');
select ok((select status='completed' and completion_status='none' and finished_at>=started_at from public.workout_sessions where id=current_setting('body_test.session')::uuid),'completed lifecycle with no sets remains none');
select set_config('body_test.finish_time',(select finished_at::text from public.workout_sessions where id=current_setting('body_test.session')::uuid),true);
select lives_ok($$select public.end_workout(current_setting('body_test.session')::uuid,'completed')$$,'same finish retry succeeds');
select is((select finished_at::text from public.workout_sessions where id=current_setting('body_test.session')::uuid),current_setting('body_test.finish_time'),'finish retry preserves timestamp');
select throws_ok($$select public.end_workout(current_setting('body_test.session')::uuid,'abandoned')$$,'23514',null,'finished session cannot be reclassified');
select throws_ok($$update public.workout_sessions set status='in_progress',finished_at=null where id=current_setting('body_test.session')::uuid$$,'23514',null,'terminal session cannot be reopened through direct writes');
select throws_ok($$select public.edit_workout(current_setting('body_test.session')::uuid,'move',null,current_setting('body_test.second')::uuid,-1)$$,'23514',null,'finished selections cannot be reordered through lifecycle RPC');
select throws_ok($$update public.workout_exercises set removed_at=now() where id=current_setting('body_test.second')::uuid$$,'23514',null,'finished selections cannot be soft removed directly');
select throws_ok($$delete from public.workout_exercises where id=current_setting('body_test.second')::uuid$$,'42501',null,'hard DELETE still denied');
select throws_ok($$update public.workout_exercises set position=20 where id=current_setting('body_test.second')::uuid$$,'23514',null,'direct client reorder cannot modify finished history');
select throws_ok($$insert into public.workout_exercises(owner_id,workout_session_id,position,exercise_id,exercise_name_snapshot) select auth.uid(),current_setting('body_test.session')::uuid,20,id,name from public.exercises where slug='push_up'$$,'23514',null,'direct client append cannot modify finished history');
select set_config('body_test.logged_session',public.start_ad_hoc_workout()::text,true);
select set_config('body_test.logged_item',public.edit_workout(current_setting('body_test.logged_session')::uuid,'add',(select id from public.exercises where slug='push_up'))::text,true);
insert into public.workout_sets(owner_id,workout_exercise_id,position,status,actual_reps,actual_weight_kg,completed_at) values(auth.uid(),current_setting('body_test.logged_item')::uuid,1,'completed',10,0,now());
select throws_ok($$select public.edit_workout(current_setting('body_test.logged_session')::uuid,'remove',null,current_setting('body_test.logged_item')::uuid)$$,'23514',null,'any recorded set protects its selected parent');
select lives_ok($$select public.end_workout(current_setting('body_test.logged_session')::uuid,'completed')$$,'existing recorded sets can be preserved at finish');
select is((select completion_status from public.workout_sessions where id=current_setting('body_test.logged_session')::uuid),'partial','existing recorded work is preserved without claiming full completion');
select is((select count(*)::int from public.workout_sets where workout_exercise_id=current_setting('body_test.logged_item')::uuid),1,'logged set remains intact');
select is((select count(*)::int from public.workout_exercises where workout_session_id=current_setting('body_test.session')::uuid),4,'all prior selections including removed tombstone remain');
select * from finish();
rollback;
